import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import { PageShell } from "@/components/nx/PageShell";
import { SslAurora } from "@/components/nx/SslAurora";
import {
  SslCertificates,
  type CertRow,
  type QueueInfo,
  type ServerOption,
} from "@/components/customer/SslCertificates";

export const dynamic = "force-dynamic";

type SslPayload = { certId?: string; domain?: string; renewal?: boolean };

export default async function SslPage() {
  const user = await requireUser();

  const [certificates, servers] = await Promise.all([
    db.sslCertificate.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
    }),
    db.server.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
    }),
  ]);

  const serverName = new Map(servers.map((s) => [s.id, s.hostname]));
  const myServerIds = new Set(servers.map((s) => s.id));

  // ---------------------------------------------------------------------------
  // Queue visibility.
  //
  // The worker claims ONE job at a time platform-wide — `worker/index.ts` picks
  // the oldest `status: "QUEUED"` row and awaits it inside a serial `for(;;)` —
  // so a certificate request genuinely can sit behind another tenant's long
  // MIGRATE. That happened on 2026-07-26: a request read "pending" for 13
  // minutes with nothing on screen to distinguish a queue from a crash, so the
  // customer had no way to know whether to wait or retry. Resolve the real
  // position here (this page already polls) instead of leaving them guessing.
  // ---------------------------------------------------------------------------
  const inflight = certificates.filter((c) => c.status === "PENDING" || c.status === "ISSUING");
  const queueByCert = new Map<string, QueueInfo>();

  if (inflight.length > 0) {
    const [sslJobs, running] = await Promise.all([
      db.job.findMany({
        where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
        select: { id: true, status: true, createdAt: true, payload: true },
        orderBy: { createdAt: "asc" },
      }),
      // Whatever is holding the single worker slot right now.
      db.job.findFirst({
        where: { status: "RUNNING" },
        select: { type: true, serverId: true },
        orderBy: { createdAt: "asc" },
      }),
    ]);

    for (const cert of inflight) {
      const job = sslJobs.find((j) => ((j.payload ?? {}) as SslPayload).certId === cert.id);

      // No queued or running job at all: the request cannot make progress. Say so
      // rather than spinning — the reconcile sweep will age it out, and the row is
      // deletable in the meantime.
      if (!job) {
        queueByCert.set(cert.id, {
          state: "none",
          position: 0,
          aheadCount: 0,
          queuedAtIso: cert.createdAt.toISOString(),
          blocking: null,
        });
        continue;
      }

      if (job.status === "RUNNING") {
        queueByCert.set(cert.id, {
          state: "running",
          position: 0,
          aheadCount: 0,
          queuedAtIso: job.createdAt.toISOString(),
          blocking: null,
        });
        continue;
      }

      // FIFO by createdAt, matching the worker's claim order exactly.
      const aheadCount = await db.job.count({
        where: { status: "QUEUED", createdAt: { lt: job.createdAt } },
      });
      queueByCert.set(cert.id, {
        state: "queued",
        position: aheadCount + 1,
        aheadCount,
        queuedAtIso: job.createdAt.toISOString(),
        blocking: running
          ? {
              type: running.type,
              // Only the job type is exposed, never whose server it is beyond
              // "yours or not" — enough to explain the wait, nothing more.
              mine: running.serverId ? myServerIds.has(running.serverId) : false,
            }
          : null,
      });
    }
  }

  const rows: CertRow[] = certificates.map((c) => ({
    id: c.id,
    domain: c.domain,
    status: c.status,
    issuer: c.issuer,
    autoRenew: c.autoRenew,
    serverName: c.serverId ? serverName.get(c.serverId) ?? null : null,
    issuedAt: c.issuedAt ? c.issuedAt.toISOString() : null,
    // The observed notAfter, or null. Nothing here is ever a computed guess.
    expiresAt: c.expiresAt ? c.expiresAt.toISOString() : null,
    lastError: c.lastError,
    queue: queueByCert.get(c.id) ?? null,
  }));

  // Certificate issuance needs a live, DNS-pointed server, so only offer running ones.
  const serverOptions: ServerOption[] = servers
    .filter((s) => s.status === "RUNNING")
    .map((s) => ({ id: s.id, hostname: s.hostname }));

  const transitional = inflight.length > 0;

  return (
    <>
      {transitional && <AutoRefresh />}
      <SslAurora />
      <PageShell
        eyebrow="NETWORK"
        title="SSL Certificates"
        sub="One-click Let's Encrypt certificates for domains pointed at your servers. Renewed automatically from 21 days before expiry."
        wisp={false}
        heroImage="/nx/hero-ssl-shield.webp"
      >
        <SslCertificates certificates={rows} servers={serverOptions} />
      </PageShell>
    </>
  );
}

"use client";

import { Icon } from "./Icon";
import { GlassFilters } from "./GlassFilters";

/* The page frame every account-area screen shares.
 *
 * WIDTH. These pages had no `max-width` at all, so they filled `<main>` — about
 * 1630px on a 1878px screen — while the dashboard is capped at 1520. That is
 * the whole reason they read as "very wide": nothing was holding them in. This
 * caps them at the SAME 1520 the dashboard uses, so the measure is identical
 * from page to page. (The original concept boards are tighter still, about
 * 1250 of content inside a 1536 board; `narrow` opts into that for pages whose
 * content is a single column of forms and rows rather than a grid, where a long
 * measure is genuinely harder to read.)
 *
 * HERO. Every concept screen opens the same way: a tracked magenta eyebrow, an
 * H1, one line of explanation, and the right-aligned tracked tagline block.
 * Reproducing that by hand on six pages is how six pages end up with six
 * slightly different heroes.
 */
export function PageShell({
  eyebrow, title, sub, tagline = ["SAME INFRASTRUCTURE.", "A BRIGHTER TOMORROW."],
  action, narrow = false, wisp = true, heroImage, children,
}: {
  eyebrow: string;
  title: string;
  sub?: string;
  /** The tracked block on the right. Two or three short lines, in caps. */
  tagline?: string[];
  /** Optional control in the hero's top-right (below the tagline on mobile). */
  action?: React.ReactNode;
  narrow?: boolean;
  /**
   * The static radial-gradient patch behind the header. Every other page with
   * its OWN animated aurora (Mail, Billing, Team, Support...) doesn't render
   * this header at all — it hand-rolls one and skips the wisp entirely, which
   * is why they never collided with it. Tools is the first page to keep using
   * this shared header while ALSO mounting a dedicated aurora underneath, and
   * the two stacked into a visible boxy patch on top of the animated one. Set
   * `false` when the page already supplies its own atmosphere.
   */
  wisp?: boolean;
  /**
   * A large decorative illustration anchored to the header's right side (a
   * real image, not a drawn glyph — e.g. the domains globe or the SSL shield).
   * Grows the header to give it real room instead of squeezing it into the
   * text row's leftover space.
   */
  heroImage?: string;
  children: React.ReactNode;
}) {
  return (
    <div className={"mx-auto flex w-full flex-col gap-4 " + (narrow ? "max-w-[1180px]" : "max-w-[1520px]")}>
      <header className={"relative overflow-hidden " + (heroImage ? "min-h-[280px] sm:min-h-[300px]" : "")}>
        {/* The aurora wisp the concept runs behind every hero. Decorative, so it
            is `pointer-events-none` and sits under the text. Skipped when a real
            hero image is present — the two washes fight for the same corner. */}
        {wisp && !heroImage && (
          <span aria-hidden
                className="pointer-events-none absolute -top-10 right-[16%] hidden h-[210px] w-[52%] opacity-70 md:block"
                style={{
                  background:
                    "radial-gradient(60% 120% at 50% 50%, rgba(64,150,255,0.20), transparent 70%)," +
                    "radial-gradient(38% 90% at 66% 42%, rgba(168,60,255,0.16), transparent 72%)",
                  filter: "blur(14px)",
                }} />
        )}
        {heroImage && (
          // eslint-disable-next-line @next/next/no-img-element -- a static hero illustration, not an optimizable content image.
          <img
            src={heroImage}
            alt=""
            aria-hidden
            className="pointer-events-none absolute -right-4 -top-6 hidden h-[280px] w-auto object-contain sm:block sm:h-[300px] lg:-right-2"
          />
        )}
        <div className="relative flex flex-wrap items-start justify-between gap-x-6 gap-y-3 pb-1">
          <div className="flex min-w-0 flex-col gap-1">
            <span className="text-[11px] font-extrabold uppercase tracking-[0.22em] text-[#f21cff]">{eyebrow}</span>
            <h1 className="text-[27px] font-extrabold leading-[1.08] tracking-[-0.032em] text-white sm:text-[31px]">
              {title}
            </h1>
            {sub && <p className="max-w-[62ch] text-[13px] leading-[1.5] text-tx-mute">{sub}</p>}
          </div>
          <div className="ml-auto flex flex-none items-center gap-4">
            <span className="hidden flex-col items-end gap-[3px] lg:flex">
              {tagline.map((l) => (
                <span key={l} className="text-[10px] font-semibold uppercase tracking-[0.28em] text-tx-faint">{l}</span>
              ))}
            </span>
            {action}
          </div>
        </div>
      </header>
      {children}
    </div>
  );
}

/** A card with the concept's header row: title left, optional control right. */
export function Panel({
  title, sub, action, className = "", bodyClass = "", style, glassId, children,
}: {
  title?: string; sub?: string; action?: React.ReactNode;
  className?: string; bodyClass?: string;
  /** For .card-glass's --tone custom property. */
  style?: React.CSSProperties;
  /** Mounts this panel's OWN <GlassFilters> and points --lens at it. Give
      every `card-glass` panel a DIFFERENT id — one filter definition shared
      by several cards is a confirmed way to ghost their text (see
      GlassFilters.tsx). Omit entirely for a panel that should not use the
      lens distortion at all. */
  glassId?: string;
  children: React.ReactNode;
}) {
  const glassStyle = glassId
    ? { ...style, "--lens": `url(#${glassId})` } as React.CSSProperties
    : style;
  return (
    <section style={glassStyle} className={"card flex min-w-0 flex-col gap-3 p-4 " + className}>
      {glassId && <GlassFilters id={glassId} />}
      {(title || action) && (
        <div className="flex flex-none items-start justify-between gap-3">
          <span className="flex min-w-0 flex-col gap-0.5">
            {title && <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">{title}</span>}
            {sub && <span className="text-[11.5px] text-tx-faint">{sub}</span>}
          </span>
          {action}
        </div>
      )}
      <div className={"flex min-w-0 flex-col " + bodyClass}>{children}</div>
    </section>
  );
}

/* One of the small figure cards the concept opens each page with: a number, a
   label, and a mark. Kept here so billing, support and activity cannot each
   invent their own version. */
export function StatCard({
  icon, value, label, foot, tone = "blue", volatileValue, bareIcon,
}: {
  icon: string; value: string; label: string; foot?: React.ReactNode;
  tone?: "blue" | "mint" | "amber" | "violet";
  /** Set when `value` is derived from the reader's locale or clock (a formatted
      date, a "3 days" countdown). Those legitimately differ between the server
      render and the browser's, and React tears the tree down over it unless it
      is told the difference is expected. */
  volatileValue?: boolean;
  /** No bordered plate behind the mark, and a larger mark so it still reads as
   *  intentional without one. Sized against the value's cap height rather than
   *  the whole text block — the first pass doubled it to 34 (51px after
   *  ICON_SCALE), which was about 2.4x the number beside it and read as
   *  oversized on every page that uses these. */
  bareIcon?: boolean;
}) {
  const ring = tone === "mint" ? "rgba(17,200,142,0.30)"
             : tone === "amber" ? "rgba(240,180,60,0.30)"
             : tone === "violet" ? "rgba(147,51,255,0.32)"
             : "rgba(47,126,239,0.32)";
  return (
    // `min-h` so a card with a `foot` line (an extra line of text under the
    // label) doesn't render visibly taller than its foot-less siblings in
    // the same stat row — every consumer mixes the two (Support's "Avg
    // response time" card only grows a foot when there's no data yet).
    <section className="card flex min-h-[88px] min-w-0 items-start gap-3 p-3.5">
      {bareIcon ? (
        <Icon name={icon} size={24} />
      ) : (
        <span className="grid h-[42px] w-[42px] flex-none place-items-center rounded-[11px] border border-rim-hi"
              style={{ background: "linear-gradient(180deg, rgba(24,74,180,0.55), rgba(4,20,60,0.9))", boxShadow: `inset 0 0 0 1px ${ring}` }}>
          <Icon name={icon} size={17} />
        </span>
      )}
      <span className="flex min-w-0 flex-col gap-0.5">
        <span suppressHydrationWarning={volatileValue} className="num text-[23px] leading-none text-white">{value}</span>
        <span className="text-[11.5px] text-tx-dim">{label}</span>
        {foot}
      </span>
    </section>
  );
}

"use client";

import { useActionState, useState, useTransition } from "react";
import Link from "next/link";
import { Icon } from "./Icon";
import { resendVerificationAction, type ResendState } from "@/lib/actions-verify-email";
import { markNotificationsRead, stopImpersonating } from "@/lib/actions-account";

/* Three pieces of portal chrome the design had no counterpart for, drawn in the
   Nexion language rather than left in the old one.
 *
 * They share a shape on purpose — one rule, one icon plate, one line of copy,
 * one action — because they interrupt the page and an interruption should be
 * the same size every time. What differs is the accent, and the accent carries
 * the whole meaning: amber asks, magenta warns, and only the impersonation bar
 * is allowed to be loud. */

/* ── the rule every banner sits on ──────────────────────────────────────────
   A hairline in the accent, brightest at the left where the icon is, fading
   out across the width. It is what makes these read as one family without
   giving each of them a heavy border. */
function AccentRule({ rgb }: { rgb: string }) {
  return (
    <span
      aria-hidden
      className="pointer-events-none absolute inset-x-0 top-0 h-px"
      style={{ background: `linear-gradient(90deg, rgba(${rgb},0.85), rgba(${rgb},0.12) 42%, transparent 80%)` }}
    />
  );
}

function Banner({
  rgb, icon, children, action, onDismiss,
}: {
  rgb: string;
  icon: string;
  children: React.ReactNode;
  action?: React.ReactNode;
  onDismiss?: () => void;
}) {
  return (
    <div
      // nx-dark-island: the wash below is a fixed dark navy tail regardless of
      // theme (an unverified-email customer must be able to read this in light
      // mode too), so the token-driven text inside it (text-white, text-tx-mute,
      // text-tx-body) needs the same "always dark chrome" token overrides the
      // rail/header/other fixed-dark surfaces get — see .nx-dark-island in
      // globals.css. Without it those tokens flip to light-mode ink and vanish
      // against this background.
      className="nx-dark-island relative flex items-center gap-3 overflow-hidden rounded-[12px] border px-3.5 py-2.5"
      style={{
        borderColor: `rgba(${rgb},0.28)`,
        // Barely-there wash, weighted to the left so the icon has something to
        // sit in. A full-strength fill here competes with the cards below it.
        background: `linear-gradient(96deg, rgba(${rgb},0.13), rgba(${rgb},0.05) 38%, rgba(1,15,34,0.86))`,
      }}
    >
      <AccentRule rgb={rgb} />
      <span
        className="grid h-[30px] w-[30px] flex-none place-items-center rounded-[8px]"
        style={{
          background: `rgba(${rgb},0.14)`,
          border: `1px solid rgba(${rgb},0.30)`,
          color: `rgb(${rgb})`,
          boxShadow: `inset 0 0 14px -6px rgba(${rgb},0.55)`,
        }}
      >
        <Icon name={icon} size={16} />
      </span>

      <div className="flex min-w-0 flex-1 flex-col gap-0.5">{children}</div>

      {action}
      {onDismiss && (
        <button
          onClick={onDismiss}
          aria-label="Dismiss"
          className="grid h-8 w-8 flex-none place-items-center rounded-[8px] text-tx-dim hover:bg-[rgba(72,148,255,0.08)] hover:text-white"
        >
          <Icon name="xcircle" size={16} />
        </button>
      )}
    </div>
  );
}

/* ── verify your email ──────────────────────────────────────────────────────
   Amber, not rose: nothing is broken and nothing is lost, the account simply
   cannot buy yet. The old copy led with the restriction; this leads with what
   the customer has to do, because that is the only part they can act on. */
export function VerifyEmailBanner({ email }: { email: string }) {
  /* The existing server action, not a new endpoint — and it reports the REAL
     outcome of the send. A resend button that always says "sent" is worse than
     no button: the customer stops waiting for an email that never left. */
  const [state, action, pending] = useActionState<ResendState>(resendVerificationAction, {});

  return (
    <Banner
      rgb="239,168,40"
      icon="envelope"
      action={
        state.ok ? (
          <span className="flex flex-none items-center gap-1.5 text-[12px] font-semibold text-mint">
            <Icon name="checkcircle" size={14} /> Link sent
          </span>
        ) : (
          <form action={action} className="flex-none">
            <button type="submit" disabled={pending} className="btn-ghost h-[32px] px-3.5 text-[12.5px]">
              {pending ? "Sending…" : "Resend link"}
            </button>
          </form>
        )
      }
    >
      <span className="text-[13px] font-bold text-white">Confirm your email address</span>
      <span className="trunc text-[11.5px] text-tx-mute">
        {state.error ? (
          <span className="text-rose">{state.error}</span>
        ) : (
          <>
            We sent a link to <span className="font-semibold text-tx-body">{email}</span>. Browse freely
            meanwhile — you just can&apos;t place an order until it&apos;s confirmed.
          </>
        )}
      </span>
    </Banner>
  );
}

/* ── impersonation ──────────────────────────────────────────────────────────
   The one piece here allowed to shout. An admin inside a customer's account can
   do everything the customer can, and the failure mode — forgetting which
   account you are in — is expensive. So: magenta, no dismiss button, and it
   states whose session this is rather than merely that impersonation is on. */
export function ImpersonationBanner({ adminName, targetEmail }: { adminName: string; targetEmail: string }) {
  return (
    <div
      // nx-dark-island: same reasoning as the Banner wrapper above — this bar's
      // background stays dark navy in both themes on purpose, so its
      // token-driven text needs the matching "always dark" token overrides.
      className="nx-dark-island relative flex items-center gap-3 overflow-hidden rounded-[12px] border px-3.5 py-2.5"
      style={{
        borderColor: "rgba(214,35,225,0.42)",
        background: "linear-gradient(96deg, rgba(214,35,225,0.20), rgba(140,58,233,0.10) 46%, rgba(1,15,34,0.88))",
        boxShadow: "0 0 26px -18px rgba(214,35,225,0.75)",
      }}
    >
      <AccentRule rgb="214,35,225" />
      <span
        className="dot dot-live flex-none"
        style={{ background: "#d623e1", color: "#d623e1" }}
      />
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        <span className="text-[13px] font-bold text-white">
          You are viewing Nxeon as <span className="text-magenta">{targetEmail}</span>
        </span>
        <span className="trunc text-[11.5px] text-tx-mute">
          Signed in as {adminName}. Every action you take here is recorded against this customer&apos;s account.
        </span>
      </div>
      {/* A server action, not a link: leaving an impersonated session is a
          state change and must not be reachable by a prefetch or a crawler. */}
      <form action={stopImpersonating} className="flex-none">
        <button type="submit" className="btn-ghost h-[32px] px-3.5 text-[12.5px]">
          Leave <Icon name="logout" size={14} />
        </button>
      </form>
    </div>
  );
}

/* ── notifications ──────────────────────────────────────────────────────────
   A panel hung off the topbar bell, not a page. The rail's bell already carries
   the unread pulse; this is what happens when it is clicked.

   Read and unread are separated by weight and a leading marker rather than by
   background fill — a filled row inside a translucent panel muddies the glass,
   and the whole point of the surface is that you can see the page through it. */

export type Note = {
  id: string;
  title: string;
  body: string | null;
  href: string | null;
  readAt: string | null;
  createdAt: string;
};

function when(iso: string): string {
  const m = Math.floor((Date.now() - new Date(iso).getTime()) / 60_000);
  if (m < 1) return "now";
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h`;
  return `${Math.floor(h / 24)}d`;
}

export function NotificationsPanel({
  notes, onClose, onMarkAllRead,
}: {
  notes: Note[];
  onClose: () => void;
  onMarkAllRead: () => void;
}) {
  const unread = notes.filter((n) => !n.readAt).length;
  const [, startTransition] = useTransition();

  function markAll() {
    onMarkAllRead();                                   // optimistic, local
    startTransition(() => { markNotificationsRead(); }); // durable, server
  }

  return (
    <>
      {/* Click-away. Transparent, but it must exist — a panel that only closes
          via its own button strands anyone who opened it by accident. */}
      <button aria-label="Close notifications" onClick={onClose} className="fixed inset-0 z-40 cursor-default" />

      <div
        role="dialog"
        aria-label="Notifications"
        className="absolute right-0 top-[52px] z-50 flex w-[340px] flex-col overflow-hidden rounded-[12px] border backdrop-blur-xl"
        style={{
          /* NOT `.glass`. That recipe is for panels sitting on the page ground,
             where you want to see through to it. This floats OVER content — the
             rack art and the cards behind it — and at glass opacity the rows
             were genuinely unreadable. So: near-opaque, and the blur is what
             keeps it from reading as a flat modal. */
          borderColor: "rgba(72,148,255,0.22)",
          background: "linear-gradient(180deg, rgba(3,20,44,0.975), rgba(1,11,26,0.985))",
          boxShadow: "0 24px 60px -20px rgba(0,3,10,0.95), inset 0 1px 0 rgba(150,200,255,0.07)",
        }}
      >
        <div className="flex flex-none items-center justify-between gap-3 border-b border-rim-soft px-3.5 py-2.5">
          <span className="text-[13.5px] font-extrabold tracking-[-0.02em] text-white">
            Notifications
            {unread > 0 && (
              <span className="ml-2 rounded-[5px] bg-[rgba(140,58,233,0.22)] px-1.5 py-0.5 text-[9.5px] font-bold text-[#bfa8ee]">
                {unread} new
              </span>
            )}
          </span>
          {unread > 0 && (
            <button onClick={markAll} className="text-[11.5px] font-semibold text-cyan hover:text-white">
              Mark all read
            </button>
          )}
        </div>

        {notes.length === 0 ? (
          /* An empty state that says the feature works, rather than looking
             like it failed to load. */
          <div className="flex flex-col items-center gap-1.5 px-4 py-9 text-center">
            <Icon name="bellnotify" size={22} className="opacity-40" />
            <span className="text-[12.5px] font-semibold text-tx-mute">You&apos;re all caught up</span>
            <span className="text-[11px] text-tx-faint">Deploys, invoices and ticket replies land here.</span>
          </div>
        ) : (
          <ul className="noscroll max-h-[380px] min-h-0 overflow-y-auto">
            {notes.map((n) => {
              /* Branch on the element rather than picking a component into a
                 variable: a `Link` needs a definite href, and the variable form
                 leaves TypeScript unable to prove there is one. */
              const inner = (
                <>
                  {/* the unread marker: present or absent, never a grey dot,
                      so the eye can count unread rows without reading them */}
                  <span className="flex w-[6px] flex-none justify-center pt-[6px]">
                    {!n.readAt && (
                      <span className="h-[6px] w-[6px] rounded-full bg-cyan shadow-[0_0_7px_rgba(20,197,228,0.85)]" />
                    )}
                  </span>
                  <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                    <span className={"trunc text-[12.5px] " + (n.readAt ? "text-tx-mute" : "font-bold text-white")}>
                      {n.title}
                    </span>
                    {n.body && <span className="line-clamp-2 text-[11px] leading-[1.45] text-tx-faint">{n.body}</span>}
                  </span>
                  <span className="flex-none pt-[1px] text-[10.5px] text-tx-faint">{when(n.createdAt)}</span>
                </>
              );
              const cls = "flex gap-2.5 px-3.5 py-2.5 transition-colors hover:bg-[rgba(72,148,255,0.06)]";
              return (
                <li key={n.id} className="border-b border-rim-soft last:border-0">
                  {n.href ? (
                    <Link href={n.href} className={cls}>{inner}</Link>
                  ) : (
                    <div className={cls}>{inner}</div>
                  )}
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { isLightTheme, auroraComposite, auroraStrandGradient } from "./auroraTheme";

/* SSL's own light field — same canvas technique every other account page's
 * aurora uses (sine-path ribbon strokes, additive blend, a blurred halo plus
 * a hard-edged core), its own ribbon family so it reads as this page's own:
 * violet into magenta, matching the shield-and-lock hero art's own glow
 * rather than any other page's hues.
 */
type Ribbon = {
  y: number; amp: number; freq: number; speed: number; phase: number;
  width: number; hue: [number, number]; alpha: number;
};

const RIBBONS: Ribbon[] = [
  { y: 0.22, amp: 0.14, freq: 0.9,  speed: 0.12,  phase: 0.4, width: 56, hue: [258, 288], alpha: 0.19 },
  { y: 0.34, amp: 0.17, freq: 0.7,  speed: -0.10, phase: 2.1, width: 66, hue: [278, 312], alpha: 0.16 },
  { y: 0.16, amp: 0.08, freq: 1.6,  speed: 0.19,  phase: 3.7, width: 34, hue: [266, 282], alpha: 0.18 },
  { y: 0.28, amp: 0.06, freq: 2.2,  speed: 0.24,  phase: 5.3, width: 15, hue: [270, 300], alpha: 0.22 },
];

export function SslAurora() {
  const ref = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const cv = ref.current;
    if (!cv) return;
    const ctx = cv.getContext("2d", { alpha: true });
    if (!ctx) return;

    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    let raf = 0, t = 0, running = true;

    const fit = () => {
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      const r = cv.getBoundingClientRect();
      cv.width = Math.max(1, Math.round(r.width * dpr));
      cv.height = Math.max(1, Math.round(r.height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const strand = (r: Ribbon, w: number, h: number, time: number, isLight: boolean) => {
      ctx.strokeStyle = auroraStrandGradient(ctx, r, w, isLight);
      ctx.lineWidth = r.width;
      ctx.lineCap = "round";
      ctx.beginPath();
      for (let x = 0; x <= w; x += 8) {
        const u = x / w;
        const y = h * (r.y
          + r.amp * Math.sin(u * Math.PI * 2 * r.freq + time * r.speed + r.phase)
          + r.amp * 0.4 * Math.sin(u * Math.PI * 2 * (r.freq * 1.7) - time * r.speed * 0.6));
        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.stroke();
    };

    const draw = () => {
      if (!running) return;
      const w = cv.clientWidth, h = cv.clientHeight;
      const isLight = isLightTheme();
      ctx.clearRect(0, 0, w, h);
      ctx.globalCompositeOperation = auroraComposite(isLight);
      ctx.filter = "blur(30px)";
      for (const r of RIBBONS) strand(r, w, h, t, isLight);
      ctx.filter = "blur(4px)";
      for (const r of RIBBONS) strand({ ...r, width: r.width * 0.22, alpha: r.alpha * 1.5 }, w, h, t, isLight);
      ctx.filter = "none";
      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, t, isLight);
      ctx.globalCompositeOperation = "source-over";
      t += 0.014;
      raf = requestAnimationFrame(draw);
    };

    fit();
    if (reduced) {
      t = 2.4;
      const w = cv.clientWidth, h = cv.clientHeight;
      const isLight = isLightTheme();
      ctx.globalCompositeOperation = auroraComposite(isLight);
      ctx.filter = "blur(30px)";
      for (const r of RIBBONS) strand(r, w, h, t, isLight);
      ctx.filter = "none";
      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, t, isLight);
    } else {
      raf = requestAnimationFrame(draw);
    }

    const onResize = () => fit();
    const onVis = () => {
      if (document.hidden) { running = false; cancelAnimationFrame(raf); }
      else if (!reduced && !running) { running = true; raf = requestAnimationFrame(draw); }
    };
    window.addEventListener("resize", onResize);
    document.addEventListener("visibilitychange", onVis);
    return () => {
      running = false;
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", onResize);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, []);

  return (
    <div aria-hidden
         className="pointer-events-none fixed inset-x-0 top-0 z-0 h-[460px] overflow-hidden lg:left-[76px] xl:left-[248px]">
      <canvas ref={ref} className="h-full w-full opacity-80" />
      <span className="nx-aurora-dot" style={{ left: "16%", top: "18%", animationDelay: "0.3s" }} />
      <span className="nx-aurora-dot" style={{ left: "40%", top: "10%", animationDelay: "1.9s" }} />
      <span className="nx-aurora-dot" style={{ left: "62%", top: "22%", animationDelay: "3.1s" }} />
      <span className="nx-aurora-dot" style={{ left: "82%", top: "13%", animationDelay: "1.1s" }} />
      <span className="absolute inset-0"
            style={{ background: "linear-gradient(180deg, color-mix(in srgb, var(--color-bg) 6%, transparent) 0%, color-mix(in srgb, var(--color-bg) 32%, transparent) 46%, color-mix(in srgb, var(--color-bg) 78%, transparent) 76%, var(--color-bg) 98%)" }} />
    </div>
  );
}

