// Screenshot the deployed v2 portal as the design customer account.
//
//   node scripts/shot.mjs <out-dir> <path> [path...]
//
// Capture-only: logs in, visits each path, writes <out-dir>/<slug>.png.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const [out, ...paths] = process.argv.slice(2);
if (!out || !paths.length) {
  console.error("usage: node scripts/shot.mjs <out-dir> <path> [path...]");
  process.exit(1);
}
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();

await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
await page.fill('input[type="email"], input[name="email"]', EMAIL);
await page.fill('input[type="password"], input[name="password"]', PASS);
await Promise.all([
  page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 45000 }).catch(() => {}),
  page.click("button.btn-primary"),
]);

for (const p of paths) {
  const slug = p.replace(/^\//, "").replace(/[^a-z0-9]+/gi, "-") || "root";
  try {
    await page.goto(`${BASE}${p}`, { waitUntil: "networkidle", timeout: 60000 });
  } catch {
    await page.waitForTimeout(3000);
  }
  await page.waitForTimeout(2500);
  const file = join(out, `${slug}.png`);
  await page.screenshot({ path: file, fullPage: true });
  console.log(`${p} -> ${file}`);
}

await browser.close();

