import Link from "next/link";
import { DomainsAurora } from "@/components/nx/DomainsAurora";

/**
 * The header the domains sub-pages (register, transfer, ideas) share, so a
 * step of the domain flow doesn't land on a completely different-looking
 * screen than the domains page it came from. Same aurora, same eyebrow/title
 * rhythm, same breathing globe — just shorter, since these pages are a task
 * rather than a hub.
 */
export function DomainsSubHero({
  title,
  sub,
  children,
}: {
  title: string;
  sub?: string;
  children: React.ReactNode;
}) {
  return (
    <>
      <DomainsAurora />
      {/* z-1: the aurora is a positioned layer and would otherwise paint over
          this content — see the domains page for the full note. */}
      <div className="relative z-[1] mx-auto flex w-full max-w-[1520px] flex-col">
        <header className="relative min-h-[150px] pt-1">
          {/* eslint-disable-next-line @next/next/no-img-element -- static hero art */}
          <img
            src="/nx/hero-domains-globe.webp"
            alt=""
            aria-hidden
            className="nx-breathe pointer-events-none absolute right-[13%] -top-2 hidden h-[150px] w-auto object-contain lg:block xl:h-[168px]"
          />
          <div className="relative flex flex-wrap items-end justify-between gap-4 pt-6">
            <div className="max-w-[620px]">
              <span className="text-[11px] font-extrabold uppercase tracking-[0.24em] text-[#f21cff]">Network</span>
              <h1 className="mt-2 text-[32px] font-extrabold leading-[1.06] tracking-[-0.032em] text-white sm:text-[36px]">
                {title}
              </h1>
              {sub && <p className="mt-2 text-[14px] text-tx-dim">{sub}</p>}
            </div>
            <Link
              href="/dashboard/domains"
              className="relative z-[2] rounded-[10px] border border-rim-hi bg-well px-3.5 py-2 text-[12.5px] font-semibold text-tx-dim transition hover:text-white"
            >
              ← All domains
            </Link>
          </div>
        </header>

        <div className="mt-7 border-t border-rim-soft pt-6">{children}</div>
      </div>
    </>
  );
}

